        en: { name: 'Khop Chai Deu', description: 'A spacious restaurant in a colonial mansion near the Nam Phou fountain, serving Lao, French and Vietnamese food. A shaded courtyard, charcoal barbecue and evening music.', tip: 'Order the Lao barbecue sin dat or a laap salad. Come for dinner around 19:00 when the courtyard is lively, and you can pay by card or in kip.' },
        es: { name: 'Khop Chai Deu', description: 'Un amplio restaurante en una mansión colonial cerca de la fuente de Nam Phou, con cocina laosiana, francesa y vietnamita. Patio con sombra, barbacoa al carbón y música por la noche.', tip: 'Pide la barbacoa laosiana sin dat o una ensalada laap. Ve a cenar hacia las 19:00, cuando el patio está animado, y se paga con tarjeta o en kips.' },
        de: { name: 'Khop Chai Deu', description: 'Ein geräumiges Restaurant in einer Kolonialvilla nahe dem Nam-Phou-Brunnen mit laotischer, französischer und vietnamesischer Küche. Schattiger Innenhof, Holzkohle-Barbecue und abends Livemusik.', tip: 'Bestell das laotische Barbecue Sin Dat oder einen Laap-Salat. Komm gegen 19 Uhr zum Abendessen, wenn der Hof belebt ist; gezahlt wird mit Karte oder in Kip.' },
        fr: { name: 'Khop Chai Deu', description: 'Un grand restaurant dans une demeure coloniale près de la fontaine de Nam Phou, qui sert une cuisine lao, française et vietnamienne. Cour ombragée, barbecue au charbon et musique le soir.', tip: 'Commandez le barbecue lao sin dat ou une salade laap. Venez dîner vers 19 h, quand la cour est animée ; on paie par carte ou en kips.' },
        it: { name: 'Khop Chai Deu', description: 'Un ampio ristorante in una villa coloniale vicino alla fontana di Nam Phou, con cucina laotiana, francese e vietnamita. Cortile ombreggiato, barbecue alla brace e musica la sera.', tip: 'Ordina il barbecue laotiano sin dat o un’insalata laap. Vai a cena verso le 19:00, quando il cortile è animato, e paga con carta o in kip.' },
